package com.yeyamo_mobile.api.gamification_service.infrastructure.persistence;import java.time.Instant;import java.util.UUID;import jakarta.persistence.*;import com.yeyamo_mobile.api.gamification_service.domain.RewardStatus;
@Entity@Table(name="gamification_rewards")public class RewardEntity{@Id UUID id;@Column(name="user_id",nullable=false,length=120)String userId;@Column(name="reward_code",nullable=false,length=100)String rewardCode;@Column(nullable=false,length=200)String title;@Enumerated(EnumType.STRING)@Column(nullable=false,length=30)RewardStatus status;@Column(name="granted_at",nullable=false)Instant grantedAt;@Column(name="claimed_at")Instant claimedAt;@Column(nullable=false,length=120)String source;@Version long version;}
